      const rec = f.rec;
      if (!rec || !rec.ctx || !rec.node.isConnected || decals.get(rec.el) !== rec) { state.fxQueue.splice(i, 1); continue; }
      const rIn = f.stage === 0 ? 0 : f.radii[f.stage - 1];
