    if (!vmEnabled()) { if (vm.node) clearViewmodel(); return; }
    if (!vm.node || !vm.node.isConnected) { clearViewmodel(); buildViewmodel(); }
    vmLiftAmmo();
    vmPlace();   // SPEC-crosshair §C: 창 크기가 바뀌면 다시 계산한다 (and a viewmodelScale write lands here too)
    vmVisibility();
